// @FIGURE_CODE_BEGIN
var CVW = 780, CVH = 600;
var figDraw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
figDraw.viewbox(0, 0, CVW, CVH);
figDraw.rect(CVW, CVH).fill('#ffffff');

var NAVY = '#1F3F66', ORANGE = '#E8622A', INK = '#111111', GREY = '#666666';
var cx = 285, cy = 300, AX = 248, LO = 248, unit = 107;
var aW = 2.0, bW = 1.3;                 // semi-axes in world units
var PHI = 35 * Math.PI / 180;           // fixed tilt of the ellipse
var cosPhi = Math.cos(PHI), sinPhi = Math.sin(PHI);
var IA = 1 / (aW * aW), IB = 1 / (bW * bW);
var MAXB = Math.abs(IA - IB);

var state = { theta: 35, primed: false, selT: null };

/* ---------- helpers ---------- */
function polar(ang, r) { return { x: cx + r * Math.cos(ang), y: cy - r * Math.sin(ang) }; }
function S(X, Y) { return { x: cx + X * unit, y: cy - Y * unit }; }

function label(g, str, x, y, size, fill, opts) {
  opts = opts || {};
  var t = g.text(str).leading(0).font({
    family: opts.family || 'Helvetica, Arial, sans-serif',
    size: size,
    anchor: opts.anchor || 'start',
    style: opts.italic ? 'italic' : 'normal',
    weight: opts.weight || 'normal'
  }).fill(fill).attr({ x: x, y: y, 'dominant-baseline': 'middle' });
  if (opts.halo !== 0) {
    t.attr({ 'paint-order': 'stroke', stroke: '#fff', 'stroke-width': opts.halo || 3, 'stroke-linejoin': 'round' });
  }
  return t;
}

function head(g, x, y, dx, dy, color, L, Wd) {
  var px = -dy, py = dx;
  g.polygon([[x, y], [x - dx * L + px * Wd, y - dy * L + py * Wd], [x - dx * L - px * Wd, y - dy * L - py * Wd]])
    .fill(color).stroke('none');
}

function dblArrow(g, ang, len, color, w) {
  var dx = Math.cos(ang), dy = -Math.sin(ang);
  g.line(cx - dx * len, cy - dy * len, cx + dx * len, cy + dy * len)
    .stroke({ color: color, width: w, linecap: 'butt' });
  head(g, cx + dx * len, cy + dy * len, dx, dy, color, 16, 5.6);
  head(g, cx - dx * len, cy - dy * len, -dx, -dy, color, 16, 5.6);
}

function ellipsePt(t) {
  var u = aW * Math.cos(t), v = bW * Math.sin(t);
  return { X: u * cosPhi - v * sinPhi, Y: u * sinPhi + v * cosPhi };
}
function coeffs(ang) {
  var c = Math.cos(ang), s = Math.sin(ang);
  return { A: IA * c * c + IB * s * s, B: 2 * c * s * (IA - IB), C: IA * s * s + IB * c * c };
}
function f2(v) { return (Math.abs(v) < 0.005 ? '0.00' : Math.abs(v).toFixed(2)); }
function sgn(v) { return v < -0.005 ? ' − ' : ' + '; }

/* ---------- groups (z-order) ---------- */
var gEll = figDraw.group();
var gAxes = figDraw.group();
var gOrange = figDraw.group();
var gArc = figDraw.group();
var gDyn = figDraw.group();
var gPanelBg = figDraw.group();
var gPanel = figDraw.group();

/* ---------- static: ellipse ---------- */
var ellPts = [];
for (var i = 0; i <= 240; i++) {
  var p = ellipsePt(i / 240 * Math.PI * 2);
  var sp = S(p.X, p.Y);
  ellPts.push([sp.x, sp.y]);
}
gEll.polygon(ellPts.map(function (q) { return q[0] + ',' + q[1]; }).join(' '))
  .fill('none').stroke({ color: NAVY, width: 2.8, linejoin: 'round' });
var hit = gEll.polyline(ellPts.map(function (q) { return q[0] + ',' + q[1]; }).join(' '))
  .fill('none').stroke({ color: '#000', width: 20, opacity: 0 }).css('cursor', 'pointer');

/* ---------- static: black axes ---------- */
dblArrow(gAxes, 0, AX, INK, 1.6);
dblArrow(gAxes, Math.PI / 2, AX, INK, 1.6);
gAxes.circle(6).center(cx, cy).fill(INK);
label(gAxes, 'x', cx + AX - 18, cy + 28, 19, INK, { family: 'Georgia, serif', italic: true, weight: 'bold', anchor: 'middle' });
label(gAxes, 'y', cx, cy - AX - 20, 19, INK, { family: 'Georgia, serif', italic: true, weight: 'bold', anchor: 'middle' });

/* ---------- static: panel background ---------- */
gPanelBg.rect(190, 556).move(575, 22).radius(7).fill('#f7f8fa').stroke({ color: '#e3e6ea', width: 1 });

/* ---------- dynamic: orange frame ---------- */
function drawOrange() {
  var th = state.theta * Math.PI / 180;
  dblArrow(gOrange, th, LO, ORANGE, 2.6);
  dblArrow(gOrange, th + Math.PI / 2, LO, ORANGE, 2.6);

  var b1 = polar(th, LO + 2);
  var o1 = { x: 16 * Math.cos(th + Math.PI / 2), y: -16 * Math.sin(th + Math.PI / 2) };
  label(gOrange, 'x′', b1.x + o1.x, b1.y + o1.y, 18, ORANGE,
    { family: 'Georgia, serif', italic: true, weight: 'bold', anchor: 'middle' });

  var a2 = th + Math.PI / 2;
  var b2 = polar(a2, LO + 2);
  var o2 = { x: 16 * Math.cos(a2 + Math.PI / 2), y: -16 * Math.sin(a2 + Math.PI / 2) };
  label(gOrange, 'y′', b2.x + o2.x, b2.y + o2.y, 18, ORANGE,
    { family: 'Georgia, serif', italic: true, weight: 'bold', anchor: 'end' });

  gOrange.on('mousemove', function (e) {
    showTooltip('Rotated frame x′, y′ — it turns with θ about the origin', e);
  }).on('mouseleave', hideTooltip).on('click', function () {
    showPopup('The rotated frame',
      'The orange axes are the same origin measured at a new angle θ. Nothing about the curve changes when you turn them — only the numbers you would record for each point change.');
  }).css('cursor', 'pointer');
}

/* ---------- dynamic: angle arc ---------- */
function drawArc() {
  var th = state.theta * Math.PI / 180;
  if (state.theta < 6) return;
  var R = 80;
  var e = polar(th, R);
  var d = 'M ' + (cx + R) + ' ' + cy + ' A ' + R + ' ' + R + ' 0 0 0 ' + e.x + ' ' + e.y;
  gArc.path(d).fill('none').stroke({ color: INK, width: 1.5 });
  head(gArc, e.x, e.y, -Math.sin(th), -Math.cos(th), INK, 10, 3.6);
  var lp = polar(th / 2, R + 26);
  label(gArc, 'θ', lp.x, lp.y, 18, INK, { family: 'Georgia, serif', italic: true, anchor: 'middle', halo: 3 });
  label(gArc, '= ' + state.theta + '°', lp.x + 12, lp.y + 17, 11, GREY, { halo: 3 });
  gArc.on('mousemove', function (ev) { showTooltip('θ = ' + state.theta + '° : rotation of the x′,y′ frame', ev); })
    .on('mouseleave', hideTooltip).css('cursor', 'pointer');
}

/* ---------- dynamic: marked point + projections ---------- */
function drawPoint() {
  if (state.selT === null) return;
  var th = state.theta * Math.PI / 180;
  var ct = Math.cos(th), st = Math.sin(th);
  var P = ellipsePt(state.selT);
  var sp = S(P.X, P.Y);

  // faint construction semi-axes of the ellipse
  var A1 = S(aW * cosPhi, aW * sinPhi), A2 = S(-aW * cosPhi, -aW * sinPhi);
  var B1 = S(-bW * sinPhi, bW * cosPhi), B2 = S(bW * sinPhi, -bW * cosPhi);
  gDyn.line(A1.x, A1.y, A2.x, A2.y).stroke({ color: NAVY, width: 1, opacity: 0.45, dasharray: '5,4' });
  gDyn.line(B1.x, B1.y, B2.x, B2.y).stroke({ color: NAVY, width: 1, opacity: 0.45, dasharray: '5,4' });

  // black-frame projections
  var fx = S(P.X, 0), fy = S(0, P.Y);
  gDyn.line(sp.x, sp.y, fx.x, fx.y).stroke({ color: '#333', width: 1.1, dasharray: '4,3' });
  gDyn.line(sp.x, sp.y, fy.x, fy.y).stroke({ color: '#333', width: 1.1, dasharray: '4,3' });
  gDyn.circle(5).center(fx.x, fx.y).fill('#333');
  gDyn.circle(5).center(fy.x, fy.y).fill('#333');

  // primed-frame projections
  var xp = P.X * ct + P.Y * st;
  var yp = -P.X * st + P.Y * ct;
  var gx = S(xp * ct, xp * st);
  var gy = S(-yp * st, yp * ct);
  gDyn.line(sp.x, sp.y, gx.x, gx.y).stroke({ color: ORANGE, width: 1.1, dasharray: '4,3' });
  gDyn.line(sp.x, sp.y, gy.x, gy.y).stroke({ color: ORANGE, width: 1.1, dasharray: '4,3' });
  gDyn.circle(5).center(gx.x, gx.y).fill(ORANGE);
  gDyn.circle(5).center(gy.x, gy.y).fill(ORANGE);

  // the point
  var dot = gDyn.circle(11).center(sp.x, sp.y).fill(NAVY).stroke({ color: '#fff', width: 1.5 });
  dot.on('mousemove', function (e) {
    showTooltip('Same point: (x, y) = (' + P.X.toFixed(2) + ', ' + P.Y.toFixed(2) +
      ')   (x′, y′) = (' + xp.toFixed(2) + ', ' + yp.toFixed(2) + ')', e);
  }).on('mouseleave', hideTooltip).css('cursor', 'pointer');

  // callouts placed outward from the origin, kept inside the figure area
  var n = Math.hypot(P.X, P.Y) || 1;
  var ux = P.X / n, uy = P.Y / n;
  var lx = sp.x + ux * 22, ly = sp.y - uy * 22;
  var anchor = 'start';
  if (lx > 470) { anchor = 'end'; lx = Math.min(lx, 535); }
  ly = Math.max(40, Math.min(560, ly));
  label(gDyn, '(x, y) = (' + P.X.toFixed(2) + ', ' + P.Y.toFixed(2) + ')', lx, ly - 9, 12, INK,
    { anchor: anchor, halo: 4 });
  label(gDyn, '(x′, y′) = (' + xp.toFixed(2) + ', ' + yp.toFixed(2) + ')', lx, ly + 9, 12, ORANGE,
    { anchor: anchor, halo: 4 });
}

/* ---------- dynamic: equation / legend panel ---------- */
function drawEqLine(g, pieces, x, y, size) {
  var curx = x;
  for (var k = 0; k < pieces.length; k++) {
    var p = pieces[k];
    var t = label(g, p.s, curx, y, size, p.fill, {
      family: 'Georgia, serif', weight: p.bold ? 'bold' : 'normal', halo: 0
    });
    var w = t.bbox().width;
    if (p.hl) {
      g.rect(w + 6, size + 8).move(curx - 3, y - (size + 8) / 2).radius(3).fill(p.hl);
      t.front();
    }
    curx += w + 1;
  }
}

function drawPanel() {
  var x0 = 590, th = state.theta * Math.PI / 180;
  var cXY = coeffs(PHI);
  var cPR = coeffs(PHI - th);
  var aligned = Math.abs(cPR.B) < 0.01;

  label(gPanel, 'Rotation of axes', x0, 40, 13, '#222', { weight: 'bold', halo: 0 });

  // legend
  var rows = [[INK, 'original frame  x, y', 2], [ORANGE, 'rotated frame  x′, y′', 2.6], [NAVY, 'the conic', 2.8]];
  for (var r = 0; r < rows.length; r++) {
    var yy = 64 + r * 18;
    gPanel.line(x0, yy, x0 + 20, yy).stroke({ color: rows[r][0], width: rows[r][2] });
    label(gPanel, rows[r][1], x0 + 27, yy, 11, '#333', { halo: 0 });
  }

  label(gPanel, 'θ = ' + state.theta + '°', x0, 132, 15, ORANGE, { weight: 'bold', halo: 0 });
  label(gPanel, 'ellipse tilt  φ = 35°', x0, 152, 11, NAVY, { halo: 0 });
  gPanel.line(x0, 168, x0 + 160, 168).stroke({ color: '#dcdfe4', width: 1 });

  if (!state.primed) {
    label(gPanel, 'Equation in x, y :', x0, 186, 12, INK, { weight: 'bold', halo: 0 });
    drawEqLine(gPanel, [
      { s: f2(cXY.A) + 'x²', fill: INK },
      { s: sgn(cXY.B) + f2(cXY.B) + 'xy', fill: INK, bold: true, hl: '#e4e7ec' }
    ], x0, 210, 14);
    drawEqLine(gPanel, [{ s: sgn(cXY.C).trim() + ' ' + f2(cXY.C) + 'y² = 1', fill: INK }], x0, 232, 14);
    label(gPanel, 'the Bxy term never changes:', x0, 256, 10.5, '#555', { halo: 0 });
    label(gPanel, 'the curve is tilted in this frame', x0, 270, 10.5, '#555', { halo: 0 });
  } else {
    label(gPanel, 'Equation in x′, y′ :', x0, 186, 12, ORANGE, { weight: 'bold', halo: 0 });
    drawEqLine(gPanel, [
      { s: f2(cPR.A) + 'x′²', fill: ORANGE },
      { s: sgn(cPR.B) + f2(cPR.B) + 'x′y′', fill: ORANGE, bold: true, hl: aligned ? '#ffe2c9' : '#e4e7ec' }
    ], x0, 210, 14);
    drawEqLine(gPanel, [{ s: sgn(cPR.C).trim() + ' ' + f2(cPR.C) + 'y′² = 1', fill: ORANGE }], x0, 232, 14);
    if (aligned) {
      drawEqLine(gPanel, [{ s: 'x′²/a² + y′²/b² = 1', fill: ORANGE, bold: true, hl: '#ffe2c9' }], x0, 258, 13);
      label(gPanel, 'standard form — no xy term', x0, 278, 10.5, '#8a4520', { halo: 0 });
    } else {
      label(gPanel, 'still tilted in this frame:', x0, 258, 10.5, '#555', { halo: 0 });
      label(gPanel, 'cross term has not vanished', x0, 272, 10.5, '#555', { halo: 0 });
    }
  }

  // cross-term magnitude bar
  label(gPanel, 'cross-term size  |B′|  in x′, y′', x0, 300, 10.5, '#444', { halo: 0 });
  gPanel.rect(160, 10).move(x0, 309).radius(5).fill('#e6e9ee');
  var wBar = 160 * Math.min(1, Math.abs(cPR.B) / MAXB);
  if (wBar > 1) gPanel.rect(wBar, 10).move(x0, 309).radius(5).fill(aligned ? '#8fbf6a' : ORANGE);
  label(gPanel, 'B′ = ' + (cPR.B < -0.005 ? '−' : (cPR.B > 0.005 ? '+' : '')) + f2(cPR.B) +
    (aligned ? '   ← vanishes!' : ''), x0, 334, 11, aligned ? '#3c7d1e' : '#444',
    { weight: aligned ? 'bold' : 'normal', halo: 0 });
  label(gPanel, 'B′ = sin 2(φ − θ) · (1/a² − 1/b²)', x0, 352, 10, '#777', { family: 'Georgia, serif', halo: 0 });
  gPanel.line(x0, 368, x0 + 160, 368).stroke({ color: '#dcdfe4', width: 1 });

  if (state.selT === null) {
    label(gPanel, 'Click the navy ellipse to mark', x0, 386, 11, '#666', { halo: 0 });
    label(gPanel, 'a point and compare frames.', x0, 402, 11, '#666', { halo: 0 });
  } else {
    var P = ellipsePt(state.selT);
    var xp = P.X * Math.cos(th) + P.Y * Math.sin(th);
    var yp = -P.X * Math.sin(th) + P.Y * Math.cos(th);
    label(gPanel, 'One point, two readings', x0, 386, 12, '#222', { weight: 'bold', halo: 0 });
    label(gPanel, '(x, y) = (' + P.X.toFixed(2) + ', ' + P.Y.toFixed(2) + ')', x0, 408, 12, INK, { halo: 0 });
    label(gPanel, '(x′, y′) = (' + xp.toFixed(2) + ', ' + yp.toFixed(2) + ')', x0, 428, 12, ORANGE, { halo: 0 });
    label(gPanel, 'x′ = x cos θ + y sin θ', x0, 452, 11, '#555', { family: 'Georgia, serif', halo: 0 });
    label(gPanel, 'y′ = −x sin θ + y cos θ', x0, 468, 11, '#555', { family: 'Georgia, serif', halo: 0 });
  }

  gPanel.rect(190, 556).move(575, 22).fill('#fff').opacity(0)
    .css('cursor', 'pointer')
    .on('mousemove', function (e) { showTooltip('Click for the key idea behind removing the xy term', e); })
    .on('mouseleave', hideTooltip)
    .on('click', function () {
      showPopup('Why the xy term disappears',
        'The xy term is not a property of the curve; it is a symptom of measuring a tilted curve with untilted axes. Its coefficient in the rotated frame is B′ = sin 2(φ − θ)(1/a² − 1/b²), so it is zero exactly when θ equals the curve\'s own tilt φ. Rotate past that angle and the term returns with the opposite sign.');
    });
}

function render() {
  gOrange.clear(); gArc.clear(); gDyn.clear(); gPanel.clear();
  drawOrange(); drawArc(); drawPoint(); drawPanel();
}

/* ---------- interactions ---------- */
function update_thetaRotation(v) { state.theta = v; render(); }
function toggle_equationFrame(on) { state.primed = !!on; render(); }
function trigger_align() {
  var sl = document.getElementById('thetaRotationInput');
  sl.value = 35; document.getElementById('thetaRotationVal').value = 35;
  update_thetaRotation(35);
}
function trigger_clearPoint() { state.selT = null; render(); }

function svgPointOf(e) {
  var r = figDraw.node.getBoundingClientRect();
  var s = Math.min(r.width / CVW, r.height / CVH);
  var ox = (r.width - CVW * s) / 2, oy = (r.height - CVH * s) / 2;
  return { x: (e.clientX - r.left - ox) / s, y: (e.clientY - r.top - oy) / s };
}

hit.on('mousemove', function (e) {
  showTooltip('The conic — its own axes are tilted 35° from x, y. Click to mark a point.', e);
}).on('mouseleave', hideTooltip).on('click', function (e) {
  var q = svgPointOf(e);
  var Xw = (q.x - cx) / unit, Yw = (cy - q.y) / unit;
  var best = 0, bd = 1e9;
  for (var k = 0; k < 720; k++) {
    var t = k / 720 * Math.PI * 2, p = ellipsePt(t);
    var d = (p.X - Xw) * (p.X - Xw) + (p.Y - Yw) * (p.Y - Yw);
    if (d < bd) { bd = d; best = t; }
  }
  state.selT = best;
  render();
});

gAxes.on('mousemove', function (e) { showTooltip('Original frame x, y — fixed, never rotates', e); })
  .on('mouseleave', hideTooltip)
  .on('click', function () {
    showPopup('The original frame',
      'These axes stay put. Because the ellipse is tilted relative to them, its equation measured here must include a cross term: 0.36x² − 0.32xy + 0.48y² = 1.');
  }).css('cursor', 'pointer');

/* ---------- demo step player ---------- */
var STEPS = [
  { title: 'A tilted ellipse in the standard frame', narration: 'With θ set to 0 the orange axes sit exactly on top of the black ones, but the ellipse is still drawn tilted, so its equation in x and y carries a nonzero Bxy term.', th: 0, pr: false },
  { title: 'Turn the frame toward the ellipse', narration: 'Drag θ upward and watch the orange axes swing counterclockwise while the black axes stay put; the cross-term coefficient shrinks as x′ approaches the ellipse\'s long axis.', th: 20, pr: false },
  { title: 'The alignment angle', narration: 'At θ ≈ 35° the x′-axis lies along the major axis and the y′-axis along the minor axis; the ellipse now looks "straight" in the rotated frame.', th: 35, pr: false },
  { title: 'The cross term disappears', narration: 'Switch the equation panel to the primed frame: the same curve is just x′²/a² + y′²/b² = 1 — standard form, no xy term at all.', th: 35, pr: true },
  { title: 'One point, two coordinate pairs', narration: 'Click any point on the ellipse to drop projections onto both frames; the point never moves, but its (x, y) and (x′, y′) readouts differ, which is exactly what the rotation formulas convert between.', th: 35, pr: true },
  { title: 'Over-rotate and lose it again', narration: 'Push θ past the alignment angle and the cross term returns with the opposite sign — the simplification happens at one specific θ, not at any rotation.', th: 65, pr: false }
];
var curStep = 2;

function applyStep(i) {
  curStep = (i + STEPS.length) % STEPS.length;
  var s = STEPS[curStep];
  var sl = document.getElementById('thetaRotationInput');
  sl.value = s.th; document.getElementById('thetaRotationVal').value = s.th;
  var cb = document.getElementById('equationFrameInput');
  cb.checked = s.pr;
  state.theta = s.th; state.primed = s.pr;
  state.selT = (curStep === 4) ? 0.35 : null;
  document.getElementById('demoNarration').innerHTML =
    '<b>' + (curStep + 1) + '. ' + s.title + '</b><br>' + s.narration;
  document.getElementById('stepLabel').textContent = 'step ' + (curStep + 1) + ' / ' + STEPS.length;
  render();
}
function nextStep() { applyStep(curStep + 1); }
function prevStep() { applyStep(curStep - 1); }

applyStep(2);
window.__markRendered();
